create table if not exists "server_plugin_installations" ("plugin_id" text not null primary key, "installed_version" text not null, "desired_state" text not null check (desired_state in ('disabled', 'enabled')), "observed_state" text not null check (observed_state in ('disabled', 'enabled', 'failed', 'installed')), "config_json" text default '{}' not null, "installed_at" integer not null, "updated_at" integer not null, "last_error" text, "last_health_json" text, "last_health_at" integer, constraint "fk_server_plugin_installations_plugin_id" foreign key ("plugin_id") references "server_plugin_registry" ("plugin_id") on delete cascade);
create index if not exists "idx_server_plugin_installations_state" on "server_plugin_installations" ("desired_state", "observed_state", "updated_at" desc)
